export function normalizeRanges(ranges) {
  if (!Array.isArray(ranges)) throw new TypeError("ranges must be an array");
  const pairs = ranges.map((range) => {
    if (!Array.isArray(range) || range.length !== 2 || !Number.isSafeInteger(range[0]) || !Number.isSafeInteger(range[1])) throw new TypeError("each range is two safe integers");
    return range[0] <= range[1] ? [range[0], range[1]] : [range[1], range[0]];
  }).sort((left, right) => left[0] - right[0] || left[1] - right[1]);
  const merged = [];
  for (const [start, end] of pairs) {
    const last = merged.at(-1);
    if (last && start <= last[1] + 1) last[1] = Math.max(last[1], end); else merged.push([start, end]);
  }
  return merged;
}
